const CACHE='nichinichi-v10';
const ASSETS=['./','./index.html','./style.css','./app.js','./lesson-data.js','./academy.js','./mobile.js','./vocabulary.js','./vocabulary-LICENSE.txt','./OpenJLPT-NOTICE.md','./Tomoshi-LICENSE.md','./Tomoshi-NOTICE.md','./content.js','./audio-data.js','./audio-LICENSE.txt','./audio-Kanji-alive-LICENSE.md','./materials.js','./pronunciation.js','./icon.svg','./icon-192.png','./icon-512.png','./apple-touch-icon.png','./manifest.webmanifest'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('nichinichi-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return response;}).catch(()=>caches.match(e.request).then(cached=>cached||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
